function draw(ctx, time, width, height) {
    ctx.fillStyle = '#00FF00';
    ctx.fillRect(0, 0, width, height);

    const t = time;
    const duration = 20;
    const sceneCount = 1;
    const loopT = t % duration;
    const sceneDuration = duration / sceneCount;
    const currentScene = Math.floor(loopT / sceneDuration);
    const sceneProgress = (loopT % sceneDuration) / sceneDuration;
    const minSide = Math.min(width, height);

    if (currentScene === 0) {
        const unit = minSide / 860;
        ctx.save();
        ctx.translate(width * 0.5, height * 0.5 + 12 * unit);
        ctx.scale(unit, unit);
        renderPeppermintStripeRoll(ctx, sceneProgress);
        ctx.restore();
    }
}

const renderPeppermintStripeRoll = (() => {
    const stemX = -115;
    const stemBottom = 220;
    const joinY = -129;
    const bendRadius = 115;
    const hookEndY = -94;
    const bendCenterX = stemX + bendRadius;
    const hookX = bendCenterX + bendRadius;
    const bendStart = stemBottom - joinY;
    const bendEnd = bendStart + Math.PI * bendRadius;
    const trackEnd = bendEnd + hookEndY - joinY;
    const tubeRadius = 45;
    const junctionSpan = 18;
    const pitch = 102;
    const diagonal = 0.69;
    const color = {
        edge: '#632a40',
        ivory: '#fff0dc',
        berry: '#c83754',
        blush: '#e77a89',
        glint: '#ffe3d2',
    };

    function traceTube(ctx, radius) {
        ctx.beginPath();
        ctx.moveTo(stemX - radius, stemBottom);
        ctx.lineTo(stemX - radius, joinY);
        ctx.arc(bendCenterX, joinY, bendRadius + radius, Math.PI, 2 * Math.PI);
        ctx.lineTo(hookX + radius, hookEndY);
        ctx.arc(hookX, hookEndY, radius, 0, Math.PI);
        ctx.lineTo(hookX - radius, joinY);
        ctx.arc(bendCenterX, joinY, bendRadius - radius, 0, Math.PI, true);
        ctx.lineTo(stemX + radius, stemBottom);
        ctx.arc(stemX, stemBottom, radius, 0, Math.PI);
        ctx.closePath();
    }

    function blendPoint(x, y, bendX, bendY, progress) {
        const weight = progress * progress * progress * (10 + progress * (-15 + 6 * progress));
        return [x + (bendX - x) * weight, y + (bendY - y) * weight];
    }

    function trackPoint(distance, across) {
        if (distance <= bendStart - junctionSpan) {
            return [stemX - across, stemBottom - distance];
        }
        if (distance >= bendEnd + junctionSpan) {
            return [hookX + across, joinY + distance - bendEnd];
        }
        const angle = (distance - bendStart) / bendRadius;
        const radius = bendRadius + across;
        const bendX = bendCenterX - radius * Math.cos(angle);
        const bendY = joinY - radius * Math.sin(angle);
        // Blend the stripe trajectory across each straight-to-curve joint.
        if (distance < bendStart + junctionSpan) {
            const progress = (distance - bendStart + junctionSpan) / (2 * junctionSpan);
            return blendPoint(stemX - across, stemBottom - distance, bendX, bendY, progress);
        }
        if (distance > bendEnd - junctionSpan) {
            const progress = (bendEnd + junctionSpan - distance) / (2 * junctionSpan);
            return blendPoint(hookX + across, joinY + distance - bendEnd, bendX, bendY, progress);
        }
        return [bendX, bendY];
    }

    function stripe(ctx, start, width, fill) {
        const edge = tubeRadius + 2;
        const steps = 30;
        const sideSteps = 12;
        const end = start + width;
        ctx.beginPath();
        ctx.moveTo(...trackPoint(start - diagonal * edge, -edge));
        for (let i = 1; i <= steps; i++) {
            const across = -edge + 2 * edge * i / steps;
            ctx.lineTo(...trackPoint(start + diagonal * across, across));
        }
        for (let i = 1; i <= sideSteps; i++) {
            ctx.lineTo(...trackPoint(start + diagonal * edge + width * i / sideSteps, edge));
        }
        for (let i = 1; i <= steps; i++) {
            const across = edge - 2 * edge * i / steps;
            ctx.lineTo(...trackPoint(end + diagonal * across, across));
        }
        for (let i = 1; i < sideSteps; i++) {
            ctx.lineTo(...trackPoint(end - diagonal * edge - width * i / sideSteps, -edge));
        }
        ctx.closePath();
        ctx.fillStyle = fill;
        ctx.fill();
    }

    function surfaceLine(ctx, across, from, to, width, stroke) {
        const steps = Math.ceil((to - from) / 5);
        ctx.beginPath();
        ctx.moveTo(...trackPoint(from, across));
        for (let i = 1; i <= steps; i++) {
            ctx.lineTo(...trackPoint(from + (to - from) * i / steps, across));
        }
        ctx.lineWidth = width;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';
        ctx.strokeStyle = stroke;
        ctx.stroke();
    }

    return function render(ctx, progress) {
        traceTube(ctx, tubeRadius + 5.8);
        ctx.fillStyle = color.edge;
        ctx.fill();
        traceTube(ctx, tubeRadius);
        ctx.fillStyle = color.ivory;
        ctx.fill();

        ctx.save();
        ctx.clip();
        const offset = (progress * 4 % 1) * pitch;
        for (let start = offset - 2 * pitch; start <= trackEnd + 2 * pitch; start += pitch) {
            stripe(ctx, start, 43, color.berry);
            stripe(ctx, start + 55, 12, color.blush);
        }
        surfaceLine(ctx, 25, 247, bendStart + 220, 6.0, color.glint);
        surfaceLine(ctx, 25, 133, 178, 4.6, color.glint);
        ctx.restore();
    };
})();

function draw(ctx, time, width, height) {
    ctx.fillStyle = '#00FF00';
    ctx.fillRect(0, 0, width, height);

    const t = time;
    const duration = 20;
    const sceneCount = 1;
    const loopT = t % duration;
    const sceneDuration = duration / sceneCount;
    const currentScene = Math.floor(loopT / sceneDuration);
    const sceneProgress = (loopT % sceneDuration) / sceneDuration;
    const minSide = Math.min(width, height);

    if (currentScene === 0) {
        const unit = minSide / 840;
        ctx.save();
        ctx.translate(width * 0.5, height * 0.5 + 3 * unit);
        ctx.scale(unit, unit);
        renderAdventCalendar(ctx, sceneProgress, sceneDuration);
        ctx.restore();
    }
}

const renderAdventCalendar = (() => {
    const tau = Math.PI * 2;
    const columns = 6;
    const rows = 4;
    const doorWidth = 67;
    const doorHeight = 75;
    const color = {
        edge: '#272440',
        frame: '#3c3867',
        indigo: '#4d497f',
        indigoLight: '#625a94',
        header: '#403965',
        well: '#3d335b',
        wellTrim: '#524371',
        shadow: '#2c2649',
        ivory: '#fae6d0',
        ivoryLight: '#fff2df',
        ivoryShade: '#e8c4b1',
        emboss: '#efd3be',
        copperEdge: '#8b4d57',
        copper: '#bf7964',
        copperLight: '#e4a685',
        gold: '#efb974',
        goldLight: '#ffdd9d',
    };
    const activeDoors = {
        1: { kind: 0, start: 0, peak: 4.65, close: 16.50, finish: 20 },
        8: { kind: 1, start: 4.65, peak: 8.10, close: 15.70, finish: 19.00 },
        15: { kind: 2, start: 7.05, peak: 10.55, close: 14.80, finish: 18.00 },
        22: { kind: 3, start: 9.45, peak: 13.50, close: 14.05, finish: 16.95 },
    };

    function ease(value, start, end) {
        const p = Math.max(0, Math.min(1, (value - start) / (end - start)));
        return p * p * p * (10 + p * (-15 + 6 * p));
    }

    function paint(ctx, fill) {
        ctx.fillStyle = fill;
        ctx.fill();
    }

    function rounded(ctx, x, y, w, h, r, fill) {
        ctx.beginPath();
        ctx.roundRect(x, y, w, h, r);
        paint(ctx, fill);
    }

    function circle(ctx, x, y, r, fill) {
        ctx.beginPath();
        ctx.arc(x, y, r, 0, tau);
        paint(ctx, fill);
    }

    function diamond(ctx, x, y, rx, ry, fill) {
        ctx.beginPath();
        ctx.moveTo(x, y - ry);
        ctx.lineTo(x + rx, y);
        ctx.lineTo(x, y + ry);
        ctx.lineTo(x - rx, y);
        ctx.closePath();
        paint(ctx, fill);
    }

    function star(ctx, radius, innerRadius, fill) {
        ctx.beginPath();
        for (let i = 0; i < 10; i++) {
            const angle = i * tau / 10 - Math.PI / 2;
            const r = i % 2 === 0 ? radius : innerRadius;
            const x = r * Math.cos(angle);
            const y = r * Math.sin(angle);
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
        paint(ctx, fill);
    }

    function backboard(ctx, phase) {
        rounded(ctx, -277, -261, 554, 516, 29, color.edge);
        rounded(ctx, -270, -254, 540, 502, 24, color.frame);
        rounded(ctx, -259, -243, 518, 480, 19, color.indigo);
        rounded(ctx, -247, -239, 494, 5.5, 2.75, color.indigoLight);
        rounded(ctx, -205, -229, 410, 63, 16, color.header);
        for (const side of [-1, 1]) {
            rounded(ctx, side * 116 - 48, -200, 96, 3, 1.5, color.copper);
            diamond(ctx, side * 177, -198.5, 4.1, 5.3, color.copperLight);
        }
        ctx.save();
        ctx.translate(0, -198);
        ctx.rotate(0.066 * Math.sin(2 * phase + 0.18));
        star(ctx, 30, 14.2, color.copperEdge);
        star(ctx, 25.2, 11.7, color.gold);
        diamond(ctx, 0, 0, 5.2, 8.1, color.goldLight);
        ctx.restore();
        rounded(ctx, -64, 223, 128, 3, 1.5, color.indigoLight);
    }

    function snowEmblem(ctx) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const a = i * tau / 6;
            const u = Math.cos(a);
            const v = Math.sin(a);
            ctx.moveTo(0, 0);
            ctx.lineTo(13.1 * u, 13.1 * v);
            ctx.moveTo(7.1 * u, 7.1 * v);
            ctx.lineTo(10.7 * u - 2.8 * v, 10.7 * v + 2.8 * u);
            ctx.moveTo(7.1 * u, 7.1 * v);
            ctx.lineTo(10.7 * u + 2.8 * v, 10.7 * v - 2.8 * u);
        }
        ctx.lineWidth = 2.1;
        ctx.lineCap = 'round';
        ctx.strokeStyle = color.goldLight;
        ctx.stroke();
    }

    function giftEmblem(ctx) {
        rounded(ctx, -10.5, -3, 21, 15, 2.4, color.gold);
        rounded(ctx, -12.5, -7, 25, 6.6, 2.2, color.goldLight);
        rounded(ctx, -1.8, -7, 3.6, 19, 1.8, color.copper);
        ctx.beginPath();
        ctx.moveTo(0, -7);
        ctx.bezierCurveTo(-6, -15, -10, -10, -7, -8);
        ctx.quadraticCurveTo(-5, -6, 0, -7);
        ctx.bezierCurveTo(6, -15, 10, -10, 7, -8);
        ctx.quadraticCurveTo(5, -6, 0, -7);
        ctx.lineWidth = 2.2;
        ctx.lineJoin = 'round';
        ctx.strokeStyle = color.goldLight;
        ctx.stroke();
    }

    function firEmblem(ctx) {
        rounded(ctx, -2.5, 8, 5, 6, 1.5, color.copperLight);
        ctx.beginPath();
        ctx.moveTo(0, -14);
        ctx.lineTo(7.5, -4);
        ctx.lineTo(4.4, -4);
        ctx.lineTo(10, 3);
        ctx.lineTo(6.6, 3);
        ctx.lineTo(12.4, 10);
        ctx.lineTo(-12.4, 10);
        ctx.lineTo(-6.6, 3);
        ctx.lineTo(-10, 3);
        ctx.lineTo(-4.4, -4);
        ctx.lineTo(-7.5, -4);
        ctx.closePath();
        paint(ctx, color.goldLight);
    }

    function motif(ctx, kind) {
        if (kind === 0) star(ctx, 13.8, 6.0, color.goldLight);
        if (kind === 1) snowEmblem(ctx);
        if (kind === 2) giftEmblem(ctx);
        if (kind === 3) firEmblem(ctx);
    }

    function panelFace(ctx, accent) {
        rounded(ctx, 0, 0, doorWidth, doorHeight, 5.8, color.ivoryShade);
        rounded(ctx, 2.6, 2.6, doorWidth - 5.2, doorHeight - 7, 4.4, color.ivory);
        rounded(ctx, 7, 5.1, doorWidth - 14, 3.3, 1.65, color.ivoryLight);
        diamond(ctx, 26, doorHeight * 0.5, 6, 8, accent ? color.ivoryShade : color.emboss);
        rounded(ctx, 49.5, 31.5, 7.5, 12, 3, color.copperEdge);
        rounded(ctx, 51, 32.8, 4.5, 8.8, 2.1, color.copperLight);
    }

    function cell(ctx, x, y, active, clock) {
        const opening = active
            ? ease(clock, active.start, active.peak) - ease(clock, active.close, active.finish)
            : 0;
        const angle = 1.36 * opening;
        const scaleX = Math.cos(angle);
        const shadowWidth = doorWidth * scaleX + 4.5 * Math.sin(angle);

        ctx.save();
        ctx.translate(x, y);
        rounded(ctx, -3, -3, doorWidth + 6, doorHeight + 6, 8, color.edge);
        rounded(ctx, 0, 0, doorWidth, doorHeight, 5.8, color.well);
        ctx.clip();
        rounded(ctx, 4, 4, doorWidth - 8, doorHeight - 8, 5, color.wellTrim);
        ctx.fillStyle = color.shadow;
        ctx.fillRect(0, 0, shadowWidth, doorHeight);

        if (active) {
            const reveal = ease(opening, 0.74, 0.97);
            if (reveal > 0) {
                ctx.save();
                ctx.translate(45, doorHeight * 0.5);
                ctx.scale(reveal, reveal);
                motif(ctx, active.kind);
                ctx.restore();
            }
        }

        ctx.save();
        ctx.scale(scaleX, 1);
        panelFace(ctx, Boolean(active));
        ctx.restore();
        ctx.restore();
    }

    return function render(ctx, progress, duration) {
        const clock = progress * duration;
        backboard(ctx, progress * tau);
        for (let row = 0; row < rows; row++) {
            for (let column = 0; column < columns; column++) {
                const index = row * columns + column;
                cell(ctx, -231 + 79 * column, -147 + 94 * row, activeDoors[index], clock);
            }
        }
    };
})();

function draw(ctx, time, width, height) {
    ctx.fillStyle = '#00FF00';
    ctx.fillRect(0, 0, width, height);

    const t = time;
    const duration = 20;
    const sceneCount = 1;
    const loopT = t % duration;
    const sceneDuration = duration / sceneCount;
    const currentScene = Math.floor(loopT / sceneDuration);
    const sceneProgress = (loopT % sceneDuration) / sceneDuration;
    const minSide = Math.min(width, height);

    if (currentScene === 0) {
        const unit = minSide / 900;
        ctx.save();
        ctx.translate(width * 0.5, height * 0.5);
        ctx.scale(unit, unit);
        renderRubyPoinsettia(ctx, sceneProgress, sceneDuration);
        ctx.restore();
    }
}

const renderRubyPoinsettia = (() => {
    const tau = Math.PI * 2;
    const count = 6;
    const color = {
        edge: '#4b203b',
        hub: '#6b2846',
        hubInset: '#873350',
        goldEdge: '#a75b4c',
        gold: '#edaa62',
        goldShade: '#d58552',
        goldLight: '#ffe1a1',
    };
    const outer = {
        lengths: [275, 263, 278, 268, 279, 265],
        widths: [48, 45, 49, 46, 49, 46],
        root: 20,
        angle: -0.065,
        fold: 0.57,
        release: 0.46,
        lineWidth: 5.2,
        colors: [
            { face: '#ae3654', shade: '#882744', facet: '#c24b63', vein: '#e37c86' },
            { face: '#a12d50', shade: '#76243f', facet: '#b74360', vein: '#dc7384' },
        ],
    };
    const inner = {
        lengths: [171, 183, 173, 177, 172, 184],
        widths: [36, 37, 35, 36, 36, 38],
        root: 16,
        angle: tau / (count * 2) - 0.065,
        fold: 0.60,
        release: 0.46,
        lineWidth: 4.6,
        colors: [
            { face: '#d24760', shade: '#b43253', facet: '#e96277', vein: '#f69aa1' },
            { face: '#c73c58', shade: '#a52c4d', facet: '#df576f', vein: '#f08c99' },
        ],
    };

    function ease(time, start, end) {
        const p = Math.max(0, Math.min(1, (time - start) / (end - start)));
        return p * p * p * (10 + p * (-15 + 6 * p));
    }

    function paint(ctx, fill) {
        ctx.fillStyle = fill;
        ctx.fill();
    }

    function circle(ctx, x, y, radius, fill) {
        ctx.beginPath();
        ctx.arc(x, y, radius, 0, tau);
        paint(ctx, fill);
    }

    function traceBract(ctx, length, width, lean) {
        ctx.beginPath();
        ctx.moveTo(-6.5, 5);
        ctx.bezierCurveTo(-0.39 * width, -0.18 * length, -0.91 * width, -0.35 * length, -width, -0.53 * length);
        ctx.bezierCurveTo(-1.01 * width, -0.74 * length, lean - 0.35 * width, -0.91 * length, lean - 2.7, -length + 4.0);
        ctx.quadraticCurveTo(lean, -length - 0.7, lean + 3.0, -length + 4.2);
        ctx.bezierCurveTo(lean + 0.36 * width, -0.89 * length, width, -0.71 * length, width, -0.53 * length);
        ctx.bezierCurveTo(0.92 * width, -0.35 * length, 0.40 * width, -0.18 * length, 6.5, 5);
        ctx.quadraticCurveTo(0, 11, -6.5, 5);
        ctx.closePath();
    }

    function bract(ctx, length, width, lean, palette, lineWidth) {
        traceBract(ctx, length, width, lean);
        paint(ctx, palette.face);
        ctx.save();
        ctx.clip();

        ctx.beginPath();
        ctx.moveTo(lean, -length - 4);
        ctx.bezierCurveTo(0.8 * lean, -0.79 * length, -2, -0.41 * length, 0, 8);
        ctx.lineTo(1.2 * width, 8);
        ctx.lineTo(1.2 * width + 12, -length - 4);
        ctx.closePath();
        paint(ctx, palette.shade);

        ctx.beginPath();
        ctx.moveTo(lean - 4, -length + 2);
        ctx.bezierCurveTo(-0.45 * width, -0.82 * length, -0.84 * width, -0.67 * length, -0.94 * width, -0.55 * length);
        ctx.quadraticCurveTo(-0.42 * width, -0.58 * length, 0.53 * lean - 5, -0.73 * length);
        ctx.closePath();
        paint(ctx, palette.facet);

        ctx.beginPath();
        ctx.moveTo(0, -0.13 * length);
        ctx.bezierCurveTo(-2, -0.42 * length, 0.46 * lean, -0.64 * length, 0.85 * lean, -0.87 * length);
        ctx.moveTo(0, -0.33 * length);
        ctx.lineTo(-0.61 * width, -0.51 * length);
        ctx.moveTo(0, -0.33 * length);
        ctx.lineTo(0.58 * width, -0.51 * length);
        ctx.moveTo(0.29 * lean, -0.54 * length);
        ctx.lineTo(0.36 * lean - 0.52 * width, -0.68 * length);
        ctx.moveTo(0.29 * lean, -0.54 * length);
        ctx.lineTo(0.36 * lean + 0.47 * width, -0.69 * length);
        ctx.lineWidth = 2.8;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.strokeStyle = palette.vein;
        ctx.stroke();
        ctx.restore();

        traceBract(ctx, length, width, lean);
        ctx.lineWidth = lineWidth;
        ctx.lineJoin = 'round';
        ctx.strokeStyle = color.edge;
        ctx.stroke();
    }

    function ring(ctx, layer, clock, phase, isInner) {
        for (let i = 0; i < count; i++) {
            const order = (count - 1 - i);
            const openStart = isInner ? 5.9 + 0.52 * i : 0.20 + 0.54 * i;
            const openEnd = openStart + (isInner ? 4.1 : 3.6);
            const closeStart = isInner ? 13.55 + 0.39 * order : 14.25 + 0.45 * order;
            const closeEnd = closeStart + (isInner ? 3.35 : 3.18);
            const unfurl = ease(clock, openStart, openEnd) - ease(clock, closeStart, closeEnd);
            const drift = Math.sin(2 * phase - i * 0.86 + layer.angle);
            const fold = layer.fold - layer.release * unfurl + 0.012 * drift;
            const side = i % 2 === 0 ? 1 : -1;

            ctx.save();
            ctx.rotate(layer.angle + i * tau / count);
            ctx.translate(0, -layer.root);
            ctx.rotate(side * (0.013 + 0.033 * unfurl) + 0.009 * drift);
            ctx.scale(0.956 + 0.044 * unfurl, Math.cos(fold));
            bract(ctx, layer.lengths[i], layer.widths[i], 7.5 * side, layer.colors[i % 2], layer.lineWidth);
            ctx.restore();
        }
    }

    function bud(ctx, x, y, radius) {
        circle(ctx, x, y, radius, color.goldEdge);
        circle(ctx, x, y, radius - 2.5, color.goldShade);
        circle(ctx, x - 0.9, y - 0.7, radius - 4.4, color.gold);
        circle(ctx, x - 2.4, y - 2.2, radius * 0.24, color.goldLight);
    }

    function center(ctx, clock, phase) {
        circle(ctx, 0, 0, 47, color.edge);
        circle(ctx, 0, 0, 42, color.hub);
        circle(ctx, 0, 0, 37, color.hubInset);
        const lift = ease(clock, 9.4, 13.0) - ease(clock, 14.3, 18.8);
        for (let i = 0; i < count; i++) {
            const a = -0.29 + i * tau / count;
            const radius = 10.1 + 0.75 * lift + 0.32 * Math.sin(2 * phase - i * 0.91);
            bud(ctx, 26 * Math.cos(a), 26 * Math.sin(a), radius);
        }
        bud(ctx, 0, 0, 11.6 + 0.55 * lift);
    }

    return function render(ctx, progress, duration) {
        const clock = progress * duration;
        const phase = tau * progress;
        ring(ctx, outer, clock, phase, false);
        ring(ctx, inner, clock, phase, true);
        center(ctx, clock, phase);
    };
})();

function draw(ctx, time, width, height) {
    ctx.fillStyle = '#00FF00';
    ctx.fillRect(0, 0, width, height);

    const t = time;
    const duration = 20;
    const sceneCount = 1;
    const loopT = t % duration;
    const sceneDuration = duration / sceneCount;
    const currentScene = Math.floor(loopT / sceneDuration);
    const sceneProgress = (loopT % sceneDuration) / sceneDuration;
    const minSide = Math.min(width, height);

    if (currentScene === 0) {
        const unit = minSide / 835;
        ctx.save();
        ctx.translate(width * 0.5 - 15 * unit, height * 0.5 + 25 * unit);
        ctx.scale(unit, unit);
        renderCranberryStocking(ctx, sceneProgress, sceneDuration);
        ctx.restore();
    }
}

const renderCranberryStocking = (() => {
    const tau = Math.PI * 2;
    const seamX = -61;
    const color = {
        ink: '#4d2340',
        wine: '#822746',
        cranberry: '#a63455',
        berry: '#b74363',
        weave: '#96304f',
        plum: '#713951',
        plumShade: '#602c49',
        plumLight: '#a15d77',
        rose: '#ce6e82',
        roseLight: '#e1989c',
        ivory: '#ffead4',
        ivoryShade: '#e8c5b7',
        ivoryLight: '#fff4e5',
    };

    function ease(time, start, end) {
        const p = Math.max(0, Math.min(1, (time - start) / (end - start)));
        return p * p * p * (10 + p * (-15 + 6 * p));
    }

    function paint(ctx, fill) {
        ctx.fillStyle = fill;
        ctx.fill();
    }

    function rounded(ctx, x, y, w, h, r, fill) {
        ctx.beginPath();
        ctx.roundRect(x, y, w, h, r);
        paint(ctx, fill);
    }

    function fabricPen(ctx, phase, leg, foot) {
        function point(x, y) {
            const travel = Math.max(0, Math.min(1, (y + 155) / 385));
