        return amplitude * Math.sin(swingCount * phase - swingOffset);
    }

    function chimeArcs(ctx, swingPhase, duration) {
        const strikeCycle = (swingPhase - clapperLag - Math.PI * 0.5) / Math.PI;
        const lastStrike = Math.floor(strikeCycle);
        const age = (strikeCycle - lastStrike) * duration / (swingCount * 2);
        const span = ease(age, 0, 0.23) * (1 - ease(age, 0.48, 1.02));
        if (span === 0) return;

        // The accent leaves from the mouth position at the strike.
        const strikePhase = (lastStrike + 0.5) * Math.PI + clapperLag;
        const strikeProgress = (strikePhase + swingOffset) / (swingCount * tau);
        const angle = swingAngle(strikeProgress);
        const x = -mouthCenterY * Math.sin(angle);
        const y = pivotY + mouthCenterY * Math.cos(angle) - 12;
        const radius = 202 + 55 * ease(age, 0, 1.02);
        const aperture = 0.145 * span;

        ctx.lineCap = 'round';
        ctx.lineWidth = 7.5 * span;
        ctx.strokeStyle = color.brassPale;
        for (const center of [angle - 0.12, angle + Math.PI + 0.12]) {
            ctx.beginPath();
            ctx.arc(x, y, radius, center - aperture, center + aperture);
            ctx.stroke();
        }
    }

    return function render(ctx, progress, duration) {
        const phase = tau * progress;
        const swingPhase = swingCount * phase - swingOffset;
        const clapperAmplitude = 0.35 + 0.024 * Math.cos(phase - 0.65);
        const relativeClapper = -clapperAmplitude * Math.sin(swingPhase - clapperLag);

        chimeArcs(ctx, swingPhase, duration);
        hanger(ctx);
        bell(ctx, swingAngle(progress), relativeClapper);
        ellipse(ctx, 0, pivotY, 10, 10, color.ink);
        ellipse(ctx, 0, pivotY, 6, 6, color.brassPale);
    };
})();

function draw(ctx, time, width, height) {
    ctx.fillStyle = '#00FF00';
    ctx.fillRect(0, 0, width, height);

    const t = time;
    const duration = 20;
    const sceneCount = 1;
    const loopT = t % duration;
    const sceneDuration = duration / sceneCount;
    const currentScene = Math.floor(loopT / sceneDuration);
    const sceneProgress = (loopT % sceneDuration) / sceneDuration;
    const minSide = Math.min(width, height);

    if (currentScene === 0) {
        const unit = minSide / 880;
        ctx.save();
        ctx.translate(width * 0.5, height * 0.5 - 20 * unit);
        ctx.scale(unit, unit);
        renderVelvetRibbonGift(ctx, sceneProgress, sceneDuration);
        ctx.restore();
    }
}

const renderVelvetRibbonGift = (() => {
    const tau = Math.PI * 2;
    const color = {
        ink: '#45192e',
        wine: '#751d39',
        berry: '#962744',
        velvet: '#a6304d',
        rose: '#b8425c',
        darkRose: '#8b233e',
        blush: '#d26072',
        cream: '#ffebd8',
        creamShade: '#efc5ad',
        copperEdge: '#753647',
        copperDark: '#a75245',
        copper: '#cc7957',
        copperMid: '#dc8c65',
        copperLight: '#f6b889',
        copperPale: '#ffd4ad',
    };

    function ease(time, start, end) {
        const p = Math.max(0, Math.min(1, (time - start) / (end - start)));
        return p * p * p * (10 + p * (-15 + 6 * p));
    }

    function rounded(ctx, x, y, w, h, r, fill) {
        ctx.beginPath();
        ctx.roundRect(x, y, w, h, r);
        ctx.fillStyle = fill;
        ctx.fill();
    }

    function rect(ctx, x, y, w, h, fill) {
        ctx.fillStyle = fill;
        ctx.fillRect(x, y, w, h);
    }

    function diamond(ctx, x, y, rx, ry, fill) {
        ctx.beginPath();
        ctx.moveTo(x, y - ry);
        ctx.lineTo(x + rx, y);
        ctx.lineTo(x, y + ry);
        ctx.lineTo(x - rx, y);
        ctx.closePath();
        ctx.fillStyle = fill;
        ctx.fill();
    }

    function wrapBand(ctx, top, bottom) {
        const h = bottom - top;
        rect(ctx, -42, top, 84, h, color.copperDark);
        rect(ctx, -37, top, 70, h, color.copper);
        rect(ctx, -26, top, 11, h, color.copperLight);
        rect(ctx, 20, top, 13, h, color.copperMid);
    }

    function boxBody(ctx) {
        rounded(ctx, -221, -9, 442, 246, 24, color.ink);
        rounded(ctx, -215, -3, 430, 234, 19, color.velvet);

        ctx.save();
        ctx.clip();
        rect(ctx, -215, -3, 15, 234, color.berry);
        rect(ctx, 192, -3, 23, 234, color.darkRose);
        rect(ctx, -215, 213, 430, 18, color.berry);
        wrapBand(ctx, -3, 231);

        for (const x of [-164, -107, 107, 164]) {
            for (const y of [59, 114, 169]) {
                diamond(ctx, x, y, 18, 22, color.rose);
                diamond(ctx, x, y, 11, 14, color.velvet);
                diamond(ctx, x, y, 4.5, 6, color.blush);
            }
        }
        ctx.restore();

        // The opening and front lip are fixed to the box.
        ctx.beginPath();
        ctx.moveTo(-189, -32);
        ctx.lineTo(189, -32);
        ctx.quadraticCurveTo(197, -32, 202, -25);
        ctx.lineTo(219, -4);
        ctx.quadraticCurveTo(223, 1, 220, 10);
        ctx.quadraticCurveTo(218, 16, 208, 16);
        ctx.lineTo(-208, 16);
        ctx.quadraticCurveTo(-218, 16, -220, 10);
        ctx.quadraticCurveTo(-223, 1, -219, -4);
        ctx.lineTo(-202, -25);
        ctx.quadraticCurveTo(-197, -32, -189, -32);
        ctx.closePath();
        ctx.fillStyle = color.ink;
        ctx.fill();

        ctx.beginPath();
        ctx.moveTo(-188, -26);
        ctx.lineTo(188, -26);
        ctx.quadraticCurveTo(193, -26, 196, -21);
        ctx.lineTo(210, -3);
        ctx.quadraticCurveTo(214, 3, 206, 3);
        ctx.lineTo(-206, 3);
        ctx.quadraticCurveTo(-214, 3, -210, -3);
        ctx.lineTo(-196, -21);
        ctx.quadraticCurveTo(-193, -26, -188, -26);
        ctx.closePath();
        ctx.fillStyle = color.copperMid;
        ctx.fill();

        ctx.beginPath();
        ctx.moveTo(-181, -18);
        ctx.lineTo(181, -18);
        ctx.lineTo(194, -3);
        ctx.lineTo(-194, -3);
        ctx.closePath();
        ctx.fillStyle = color.wine;
        ctx.fill();
        wrapBand(ctx, 6, 16);
    }

    function boxLid(ctx) {
        rounded(ctx, -239, -69, 478, 87, 18, color.ink);
        rounded(ctx, -233, -63, 466, 75, 13, color.berry);
        ctx.save();
        ctx.clip();
        rect(ctx, -233, -63, 466, 30, color.cream);
        rect(ctx, -233, -40, 466, 7, color.creamShade);
        rect(ctx, -233, -1, 466, 13, color.wine);
        wrapBand(ctx, -63, 12);
        ctx.restore();
    }

    function tail(ctx, extension) {
        const reach = 30 * extension;
        const lift = 10 * extension;
        ctx.beginPath();
        ctx.moveTo(-15, 6);
        ctx.bezierCurveTo(-46, 5, -93, 19 - lift, -137 - reach, 11 - lift);
        ctx.quadraticCurveTo(-143 - reach, 10 - lift, -144 - reach, 15 - lift);
        ctx.lineTo(-148 - reach, 36 - lift);
        ctx.lineTo(-130 - reach, 31 - lift);
        ctx.lineTo(-118 - reach, 46 - lift);
        ctx.bezierCurveTo(-87, 35, -49, 26, -15, 21);
        ctx.closePath();
        ctx.fillStyle = color.copperMid;
        ctx.fill();
        ctx.lineJoin = 'round';
        ctx.lineWidth = 4.5;
        ctx.strokeStyle = color.copperEdge;
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(-48, 15);
        ctx.bezierCurveTo(-71, 18, -105, 24 - lift, -134 - reach, 19 - lift);
        ctx.lineCap = 'round';
        ctx.lineWidth = 4;
        ctx.strokeStyle = color.copperPale;
        ctx.stroke();
    }

    function traceLoop(ctx) {
        ctx.beginPath();
        ctx.moveTo(-16, -5);
        ctx.bezierCurveTo(-44, -34, -100, -88, -136, -81);
        ctx.bezierCurveTo(-167, -75, -168, -48, -147, -28);
        ctx.bezierCurveTo(-126, -8, -74, -2, -18, 12);
        ctx.closePath();

        ctx.moveTo(-51, -11);
        ctx.bezierCurveTo(-77, -27, -111, -61, -134, -59);
        ctx.bezierCurveTo(-147, -57, -147, -46, -136, -36);
        ctx.bezierCurveTo(-120, -22, -83, -15, -51, -11);
        ctx.closePath();
    }

    function bowLoop(ctx, loosen, angle) {
        ctx.save();
        // Deform the ribbon around the attachment under the knot.
        ctx.translate(-17, 0);
        ctx.rotate(angle);
        ctx.scale(1 + 0.085 * loosen, 1 - 0.045 * loosen);
        ctx.translate(17, 0);

        traceLoop(ctx);
        ctx.fillStyle = color.copperMid;
        ctx.fill('evenodd');
        ctx.save();
        ctx.clip('evenodd');

        ctx.beginPath();
        ctx.moveTo(-170, -46);
        ctx.bezierCurveTo(-127, -13, -69, -11, -12, 4);
        ctx.lineTo(-12, 22);
        ctx.lineTo(-170, 4);
        ctx.closePath();
        ctx.fillStyle = color.copperDark;
        ctx.fill();

        ctx.beginPath();
        ctx.moveTo(-60, -36);
        ctx.bezierCurveTo(-85, -56, -113, -78, -135, -71);
        ctx.quadraticCurveTo(-149, -69, -153, -60);
        ctx.lineWidth = 4.5;
        ctx.lineCap = 'round';
        ctx.strokeStyle = color.copperPale;
        ctx.stroke();
        ctx.restore();

        traceLoop(ctx);
        ctx.lineJoin = 'round';
        ctx.lineWidth = 4.5;
        ctx.strokeStyle = color.copperEdge;
        ctx.stroke();
        ctx.restore();
    }

    function knot(ctx, loosen) {
        ctx.save();
        ctx.scale(1 + 0.055 * loosen, 1 - 0.04 * loosen);
        rounded(ctx, -29, -19, 58, 39, 13, color.copperEdge);
        rounded(ctx, -25, -15, 50, 31, 10, color.copper);
        rounded(ctx, -20, -12, 28, 25, 8, color.copperLight);
        rounded(ctx, -15, -9, 7, 18, 3.5, color.copperPale);
        ctx.restore();
    }

    return function render(ctx, progress, duration) {
        const clock = progress * duration;
        const phase = tau * progress;
        const lift = ease(clock, 4.65, 11.65) - ease(clock, 12.1, 18.3);
        const loosen = ease(clock, 0.35, 5.7) - ease(clock, 14.5, 19.65);
        const tailLeft = ease(clock, 5.0, 11.9) - ease(clock, 12.7, 18.65);
        const tailRight = ease(clock, 5.3, 12.25) - ease(clock, 13.0, 18.9);

        boxBody(ctx);
        ctx.save();
        ctx.translate(0, -112 * lift);
        boxLid(ctx);
        ctx.translate(0, -66);

        tail(ctx, 0.085 + 0.82 * tailLeft + 0.035 * Math.sin(2 * phase + 0.4));
        ctx.save();
        ctx.scale(-1, 1);
        tail(ctx, 0.085 + 0.82 * tailRight + 0.035 * Math.sin(2 * phase + 0.95));
        ctx.restore();

        bowLoop(ctx, loosen, 0.026 + 0.058 * loosen + 0.016 * Math.sin(2 * phase));
        ctx.save();
        ctx.scale(-1, 1);
        bowLoop(ctx, loosen, 0.026 + 0.054 * loosen + 0.016 * Math.sin(2 * phase + 0.42));
        ctx.restore();
        knot(ctx, loosen);
        ctx.restore();
    };
})();

function draw(ctx, time, width, height) {
    ctx.fillStyle = '#00FF00';
    ctx.fillRect(0, 0, width, height);

    const t = time;
    const duration = 20;
    const sceneCount = 1;
    const loopT = t % duration;
    const sceneDuration = duration / sceneCount;
    const currentScene = Math.floor(loopT / sceneDuration);
    const sceneProgress = (loopT % sceneDuration) / sceneDuration;
    const minSide = Math.min(width, height);

    if (currentScene === 0) {
        const unit = minSide / 895;
        ctx.save();
        ctx.translate(width * 0.5, height * 0.5 + 24 * unit);
        ctx.scale(unit, unit);
        renderIvoryFoldTree(ctx, sceneProgress, sceneDuration);
        ctx.restore();
    }
}

const renderIvoryFoldTree = (() => {
    const tau = Math.PI * 2;
    const closedFoldAngle = 0.54;
    const closedProjection = Math.cos(closedFoldAngle);
    const color = {
        ink: '#542940',
        ivory: '#ffecd5',
        blush: '#f3d7d6',
        crease: '#edc4b5',
        roseFold: '#a15a6b',
        plumFold: '#79405d',
        rosewood: '#823f55',
        lightWood: '#a35b61',
        copper: '#ca7554',
        goldDark: '#a96046',
        gold: '#e5a954',
        goldLight: '#ffd38b',
        champagne: '#ffe6b8',
        wine: '#922748',
        berry: '#b13956',
        berryLight: '#e18591',
    };
    const tiers = [
        { apex: -4, hem: 174, halfSpan: 231, radius: 14, openStart: 0.3, openEnd: 5.35, closeStart: 15.25, closeEnd: 19.7 },
        { apex: -78, hem: 79, halfSpan: 174, radius: 12.5, openStart: 1.95, openEnd: 7.15, closeStart: 14.7, closeEnd: 19.05 },
        { apex: -148, hem: -13, halfSpan: 127, radius: 11.5, openStart: 4.0, openEnd: 9.2, closeStart: 14.15, closeEnd: 18.35 },
        { apex: -222, hem: -105, halfSpan: 82, radius: 9, openStart: 6.1, openEnd: 11.25, closeStart: 13.55, closeEnd: 17.55 },
    ];
    const starPoints = Array.from({ length: 10 }, (_, i) => {
        const angle = -Math.PI * 0.5 + i * Math.PI / 5;
        const radius = i % 2 === 0 ? 44 : 20.5;
        return [Math.cos(angle) * radius, Math.sin(angle) * radius];
    });

    function ease(time, start, end) {
        const p = Math.max(0, Math.min(1, (time - start) / (end - start)));
        return p * p * p * (10 + p * (-15 + 6 * p));
    }

    function rounded(ctx, x, y, w, h, r, fill) {
        ctx.beginPath();
        ctx.roundRect(x, y, w, h, r);
        ctx.fillStyle = fill;
        ctx.fill();
    }

    function circle(ctx, x, y, r, fill) {
        ctx.beginPath();
        ctx.arc(x, y, r, 0, tau);
        ctx.fillStyle = fill;
        ctx.fill();
    }

    function diamond(ctx, x, y, rx, ry, fill) {
        ctx.beginPath();
        ctx.moveTo(x, y - ry);
        ctx.lineTo(x + rx, y);
        ctx.lineTo(x, y + ry);
        ctx.lineTo(x - rx, y);
        ctx.closePath();
        ctx.fillStyle = fill;
        ctx.fill();
    }

    function foot(ctx) {
        rounded(ctx, -38, 163, 76, 77, 11, color.ink);
        rounded(ctx, -33, 167, 66, 72, 8, color.rosewood);
        rounded(ctx, -25, 177, 17, 55, 5, color.lightWood);
        rounded(ctx, -62, 227, 124, 28, 10, color.ink);
        rounded(ctx, -57, 231, 114, 19, 7, color.copper);
        rounded(ctx, -47, 234, 94, 5.5, 2.75, color.goldLight);
    }

    function traceTier(ctx, apex, hem, span, cornerY) {
        ctx.beginPath();
        ctx.moveTo(-7, apex + 5);
        ctx.quadraticCurveTo(0, apex - 4, 7, apex + 5);
        ctx.lineTo(span - 9, cornerY - 9);
        ctx.quadraticCurveTo(span + 3, cornerY + 1, span - 6, cornerY + 8);
        ctx.quadraticCurveTo(span * 0.62, hem + 3, 0, hem + 13);
        ctx.quadraticCurveTo(-span * 0.62, hem + 3, -span + 6, cornerY + 8);
        ctx.quadraticCurveTo(-span - 3, cornerY + 1, -span + 9, cornerY - 9);
        ctx.closePath();
    }

    function ornament(ctx, x, y, radius, fill) {
        rounded(ctx, x - radius * 0.36, y - radius - 4, radius * 0.72, 7, 2, color.goldDark);
        rounded(ctx, x - radius * 0.27, y - radius - 3.4, radius * 0.54, 4, 1.5, color.goldLight);
        circle(ctx, x, y, radius, color.ink);
        circle(ctx, x, y, radius - 2.1, fill);
        circle(ctx, x - radius * 0.27, y - radius * 0.29, radius * 0.24, color.berryLight);
    }

    function paperTier(ctx, tier, index, clock, phase) {
        const { apex, hem, halfSpan, radius } = tier;
        const spread = ease(clock, tier.openStart, tier.openEnd) - ease(clock, tier.closeStart, tier.closeEnd);
        const drift = Math.sin(phase * 2 - index * 0.58);
        const bend = 1.7 * drift + 22 * spread;
        const foldAngle = closedFoldAngle - 0.40 * spread;
        const span = halfSpan * (Math.cos(foldAngle) / closedProjection + 0.004 * drift);
        const cornerY = hem - 20 - bend;

        traceTier(ctx, apex, hem, span, cornerY);
        ctx.fillStyle = color.ivory;
        ctx.fill();
        ctx.save();
        ctx.clip();

        // The spine is fixed while both paper wings open about it.
        ctx.fillStyle = color.blush;
        ctx.fillRect(0, apex - 6, span + 8, hem - apex + 24);
        ctx.beginPath();
        ctx.moveTo(0, apex);
        ctx.lineTo(0, hem + 4);
        ctx.lineTo(-9, hem + 2);
        ctx.lineTo(-4, apex + 25);
        ctx.closePath();
        ctx.fillStyle = color.crease;
        ctx.fill();

        ctx.beginPath();
        ctx.moveTo(-span - 8, cornerY - 4);
        ctx.quadraticCurveTo(-span * 0.54, hem - 10, 0, hem - 1);
        ctx.quadraticCurveTo(span * 0.54, hem - 10, span + 8, cornerY - 4);
        ctx.lineTo(span + 8, hem + 18);
        ctx.lineTo(-span - 8, hem + 18);
        ctx.closePath();
        ctx.fillStyle = color.roseFold;
        ctx.fill();
        ctx.save();
        ctx.clip();
        ctx.fillStyle = color.plumFold;
        ctx.fillRect(0, cornerY - 10, span + 10, hem - cornerY + 34);
        ctx.restore();

        ctx.beginPath();
        ctx.moveTo(-span - 8, cornerY - 4);
        ctx.quadraticCurveTo(-span * 0.54, hem - 10, 0, hem - 1);
        ctx.quadraticCurveTo(span * 0.54, hem - 10, span + 8, cornerY - 4);
        ctx.lineWidth = 2.9;
        ctx.strokeStyle = color.goldLight;
        ctx.stroke();

        const ornamentY = hem - (index === 3 ? 43 : 49) - bend * 0.52;
        const ornamentX = span * (index === 3 ? 0.40 : 0.51);
        ornament(ctx, -ornamentX, ornamentY, radius, index % 2 === 0 ? color.berry : color.wine);
        ornament(ctx, ornamentX, ornamentY, radius, index % 2 === 0 ? color.wine : color.berry);
        diamond(ctx, 0, hem - 23, radius * 0.49, radius * 0.73, color.goldDark);
        diamond(ctx, 0, hem - 23, radius * 0.31, radius * 0.48, color.goldLight);
        ctx.restore();

        traceTier(ctx, apex, hem, span, cornerY);
        ctx.lineWidth = 4.7;
        ctx.lineJoin = 'round';
        ctx.strokeStyle = color.ink;
        ctx.stroke();
    }

    function traceStar(ctx) {
        ctx.beginPath();
        ctx.moveTo(starPoints[0][0], starPoints[0][1]);
        for (let i = 1; i < starPoints.length; i++) {
            ctx.lineTo(starPoints[i][0], starPoints[i][1]);
        }
        ctx.closePath();
    }

    function crown(ctx, angle) {
        rounded(ctx, -6.5, -247, 13, 36, 5, color.ink);
        rounded(ctx, -3.5, -246, 7, 33, 3, color.gold);
        ctx.save();
        ctx.translate(0, -264);
        ctx.rotate(angle);
        traceStar(ctx);
        ctx.fillStyle = color.gold;
        ctx.fill();
        ctx.save();
        ctx.clip();
        ctx.beginPath();
        ctx.moveTo(0, -48);
        ctx.lineTo(5, -12);
        ctx.lineTo(45, -16);
        ctx.lineTo(12, 2);
        ctx.lineTo(28, 40);
        ctx.lineTo(0, 13);
        ctx.lineTo(-27, 40);
        ctx.lineTo(-9, 1);
        ctx.closePath();
        ctx.fillStyle = color.goldLight;
        ctx.fill();
        diamond(ctx, 0, -2, 7, 11, color.champagne);
        ctx.restore();

        traceStar(ctx);
        ctx.lineWidth = 4.8;
        ctx.lineJoin = 'round';
        ctx.strokeStyle = color.ink;
        ctx.stroke();
        ctx.restore();
    }

    return function render(ctx, progress, duration) {
        const clock = progress * duration;
        const phase = tau * progress;
        const crownTurn = ease(clock, 8.0, 12.7) - ease(clock, 14.15, 18.65);

        foot(ctx);
        for (let i = 0; i < tiers.length; i++) {
            paperTier(ctx, tiers[i], i, clock, phase);
        }
        crown(ctx, 0.016 * Math.sin(phase * 2 - 1.2) + 0.069 * crownTurn);
    };
})();
